<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Database;
use App\Services\AuditService;use App\Services\PermissionService;
final class ApiController{
 private function user():int{$h=(string)($_SERVER['HTTP_AUTHORIZATION']??'');if(!preg_match('/Bearer\s+(.+)/i',$h,$m)){http_response_code(401);exit(json_encode(['error'=>'unauthorized']));}$hash=hash('sha256',trim($m[1]));$s=Database::connection()->prepare('SELECT user_id FROM api_tokens WHERE token_hash=:h AND is_active=1 AND (expires_at IS NULL OR expires_at>SYSDATETIME())');$s->execute(['h'=>$hash]);$uid=$s->fetchColumn();if($uid===false){http_response_code(401);exit(json_encode(['error'=>'invalid_token']));}$pdo=Database::connection();$rate=$pdo->prepare("MERGE api_rate_limits WITH (HOLDLOCK) AS t USING (SELECT :h token_hash) s ON t.token_hash=s.token_hash WHEN MATCHED THEN UPDATE SET request_count=CASE WHEN DATEDIFF(SECOND,t.window_started_at,SYSDATETIME())>=60 THEN 1 ELSE t.request_count+1 END,window_started_at=CASE WHEN DATEDIFF(SECOND,t.window_started_at,SYSDATETIME())>=60 THEN SYSDATETIME() ELSE t.window_started_at END,updated_at=SYSDATETIME() WHEN NOT MATCHED THEN INSERT(token_hash,window_started_at,request_count) VALUES(:h2,SYSDATETIME(),1);");$rate->execute(['h'=>$hash,'h2'=>$hash]);$rateCount=$pdo->prepare('SELECT request_count,window_started_at FROM api_rate_limits WHERE token_hash=:h');$rateCount->execute(['h'=>$hash]);$rr=$rateCount->fetch();if($rr && (int)$rr['request_count']>60){http_response_code(429);header('Retry-After: 60');exit(json_encode(['error'=>'rate_limited']));}$s=$pdo->prepare('UPDATE api_tokens SET last_used_at=SYSDATETIME() WHERE token_hash=:h');$s->execute(['h'=>$hash]);return (int)$uid;}
 private function json(mixed $v):never{header('Content-Type: application/json; charset=utf-8');echo json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
 public function products():void{$uid=$this->user();PermissionService::require($uid,'api.products.view');$rows=Database::connection()->query('SELECT TOP 1000 p.id,p.product_code,p.product_name,u.name unit,p.importance,p.expected_sources FROM products p JOIN units u ON u.id=p.unit_id WHERE p.is_active=1 ORDER BY p.id')->fetchAll();AuditService::log($uid,'api.products');$this->json(['data'=>$rows]);}
 public function prices(int $id):void{$uid=$this->user();PermissionService::require($uid,'api.prices.view');$s=Database::connection()->prepare('SELECT pp.id,pp.product_id,pp.source_no,pp.supplier,pp.package_price,pp.unit_price,pp.price_received_at FROM product_prices pp WHERE pp.product_id=:id ORDER BY pp.price_received_at DESC,pp.id DESC');$s->execute(['id'=>$id]);AuditService::log($uid,'api.prices','product',(string)$id);$this->json(['data'=>$s->fetchAll()]);}
 public function queue():void{$uid=$this->user();PermissionService::require($uid,'api.queue.view');$rows=Database::connection()->query("SELECT TOP 500 q.*,p.product_code,p.product_name FROM price_queue q JOIN products p ON p.id=q.product_id WHERE q.status IN('new','in_progress') ORDER BY q.score DESC,q.updated_at")->fetchAll();AuditService::log($uid,'api.queue');$this->json(['data'=>$rows]);}
}